import app from 'flarum/forum/app';
import { extend } from 'flarum/common/extend';
import GlobalSearch from 'flarum/forum/components/GlobalSearch';
import LinkButton from 'flarum/common/components/LinkButton';
import extractText from 'flarum/common/utils/extractText';
import { t } from './util';
/**
 * Moments in the forum's search dropdown. The feed endpoint does the search,
 * through the same privacy rule as the feed; only an excerpt is kept.
 */
class MomentsSearchSource {
  resource = 'moments';
  results = (() => new Map())();
  title() {
    return extractText(t('search.heading'));
  }
  isCached(query) {
    return this.results.has(query.toLowerCase());
  }
  async search(query, limit) {
    query = query.toLowerCase();
    const res = await app.request({
      method: 'GET',
      url: `${app.forum.attribute('apiUrl')}/moments`,
      params: {
        filter: {
          q: query
        },
        page: {
          limit
        }
      }
    });
    const names = {};
    (res.included || []).forEach(u => names[u.id] = u.attributes.displayName);
    const parser = new DOMParser();
    this.results.set(query, (res.data || []).map(d => ({
      id: d.id,
      name: names[d.userId] || '',
      text: (parser.parseFromString(d.html || '', 'text/html').body.textContent || '').trim().slice(0, 140)
    })));
    m.redraw();
  }
  view(query) {
    return (this.results.get(query.toLowerCase()) || []).map(r => m("li", {
      className: "MomentsSearchResult",
      "data-index": 'moments' + r.id,
      "data-id": r.id
    }, m("a", {
      href: app.route('moments.show', {
        id: r.id
      })
    }, m("strong", null, r.name), " ", m("span", null, r.text))));
  }
  customGrouping() {
    return false;
  }
  fullPage(query) {
    return m("li", null, m(LinkButton, {
      icon: "fas fa-search",
      href: app.route('moments.index', {
        q: query
      })
    }, t('search.all', {
      query
    })));
  }
  gotoItem(id) {
    return app.route('moments.show', {
      id
    });
  }
}
export default function registerSearch() {
  extend(GlobalSearch.prototype, 'sourceItems', function (items) {
    if (app.forum.attribute('canViewMoments')) items.add('moments', new MomentsSearchSource(), -10);
  });
}