import app from 'flarum/forum/app';

/** A forum-side Moments string. Every word on screen comes through here. */
export const t = function (key, params) {
  if (params === void 0) {
    params = {};
  }
  return app.translator.trans(`ernestdefoe-moments.forum.${key}`, params);
};

/**
 * `flarum` is a global the bundle never imports; reached through globalThis
 * so its absence is `undefined`, not a ReferenceError thrown out of an
 * initializer.
 */
export function flarumGlobal() {
  return typeof globalThis !== 'undefined' ? globalThis.flarum : undefined;
}

/** Whether an extension with forum JS is enabled. Never a build-time import. */
export function has(id) {
  const extensions = flarumGlobal()?.extensions;
  return !!extensions && id in extensions;
}
export const apiUrl = path => app.forum.attribute('apiUrl') + path;
export const PRIVACY_ICONS = {
  public: 'fas fa-earth-americas',
  followers: 'fas fa-user-group',
  private: 'fas fa-lock'
};

/** m:ss from milliseconds. */
export function duration(ms) {
  if (!ms) return '';
  const s = Math.round(ms / 1000);
  return `${Math.floor(s / 60)}:${String(s % 60).padStart(2, '0')}`;
}

/** A topic's feed. */
export function topicHref(key) {
  return app.route('moments.index') + '?topic=' + encodeURIComponent(key.toLowerCase());
}